export interface Unit {
  code: string;
  block: string;
  typeSlug: string;
  status: UnitStatus;
  price: number;
  gridX: number; // position inside block grid
  gridZ: number;
}

// Deterministic pseudo-random generator so the layout is stable across reloads
function seeded(seed: number) {
  let s = seed;
  return () => {
    s = (s * 9301 + 49297) % 233280;
    return s / 233280;
  };
}

export const units: Unit[] = (() => {
  const rand = seeded(42);
  const list: Unit[] = [];
  blocks.forEach((block) => {
    const type = houseTypes.find((t) => t.slug === block.unitType)!;
    let n = 1;
    for (let r = 0; r < block.rows; r++) {
      for (let c = 0; c < block.cols; c++) {
        const roll = rand();
        const status: UnitStatus = roll < 0.42 ? "terjual" : roll < 0.55 ? "booking" : "tersedia";
        const priceJitter = 1 + (rand() - 0.5) * 0.08;
        list.push({
          code: `${block.code}-${n}`,
          block: block.code,
          typeSlug: type.slug,
          status,
          price: Math.round((type.priceFrom * priceJitter) / 1_000_000) * 1_000_000,
          gridX: c,
          gridZ: r,
        });
        n++;
      }
    }
  });
  return list;
})();

